struct FeatureFlags {
    let newCheckout: Bool

    static func fromEnvironment() -> FeatureFlags {
        FeatureFlags(newCheckout:
            ProcessInfo.processInfo.environment["FF_NEW_CHECKOUT"] == "1")
    }
}

func checkout(_ cart: Cart) -> Receipt {
    flags.newCheckout ? newCheckout(cart) : legacyCheckout(cart)
}
